import re
from collections import defaultdict

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    result = defaultdict(lambda: defaultdict(lambda: ''))
    current_section = 'DEFAULT'
    current_value = ''

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(';') or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            current_section = line[1:-1]
            continue
        if line.endswith('\\\n'):
            line = line[:-2]
        if '=' in line or ':' in line:
            split_index = min(line.find('='), line.find(':')) + 1
            key = line[:split_index].strip().lower()
            value = line[split_index:].strip()
            if value.startswith('"') and value.endswith('"'):
                value = value[1:-1]
            elif line.startswith('"') and line.endswith('"'):
                value = line[1:-1]
            else:
                if line.startswith(' '):
                    current_value += '\n' + line.strip()
                    continue
                current_value = value
            if key in result[current_section]:
                result[current_section][key] = current_value
            else:
                result[current_section][key] = current_value
            current_value = ''
        elif line.startswith(' '):
            if current_value:
                current_value += '\n' + line.strip()
            else:
                raise ValueError("Empty line after section header")
        else:
            raise ValueError("Key line before section header")

    for section, keys in result.items():
        for key in keys:
            if key not in result['DEFAULT']:
                continue
            if section != 'DEFAULT':
                result[section][key] = result['DEFAULT'][key]
            current_value = result[section][key]
            while True:
                match = re.search(r'\$\{(\w+):(\w+)\}', current_value)
                if match:
                    section_name, key_name = match.groups()
                    if section_name == current_section:
                        current_value = current_value.replace(f"${{{section_name}:{key_name}}}", result[section_name][key_name], 1)
                    else:
                        current_value = current_value.replace(f"${{{section_name}:{key_name}}}", result[section_name][key_name], 1)
                else:
                    break

    return {section: dict(result[section]) for section in result if section != 'DEFAULT'}

