import time
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.time):
        self.clock = clock
        self.capacity = capacity
        self.ttl = ttl
        self.hits = 0
        self.misses = 0
        self.evictions = 0
        self.expirations = 0
        self.cache = OrderedDict()

    def put(self, key, value):
        now = self.clock()
        if key in self.cache:
            self.cache[key] = (value, now + self.ttl)
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
            self.cache[key] = (value, now + self.ttl)

    def get(self, key, default=None):
        now = self.clock()
        if key in self.cache:
            value, expiry = self.cache.pop(key)
            if now >= expiry:
                self.expirations += 1
                return default
            self.cache[key] = (value, expiry)
            self.hits += 1
            return value
        self.misses += 1
        return default

    def __len__(self):
        now = self.clock()
        return sum(1 for (value, expiry) in self.cache.values() if now < expiry)

    def stats(self):
        return {"hits": self.hits, "misses": self.misses, "evictions": self.evictions, "expirations": self.expirations}
